import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_note(name: str) -> str:
    """Return the text of the file `name` inside the `notes` directory.

    `name` is untrusted and is resolved relative to `notes` (relative to the
    working directory); subdirectories are allowed (e.g. "sub/b.txt").
    Any name that would resolve outside `notes` (absolute paths, ".." parts,
    symlinks pointing outside, null bytes, etc.) yields "". A missing,
    unreadable, or non-file target also yields "".
    """
    try:
        if not name or "\x00" in name or "\\" in name:
            return ""
        if os.path.isabs(name) or Path(name).is_absolute():
            return ""
        base = Path(NOTES_DIR).resolve()
        target = (base / name).resolve()
        if not target.is_relative_to(base) or target == base:
            return ""
        if not target.is_file():
            return ""
        return target.read_text()
    except (OSError, ValueError, UnicodeError):
        return ""


@pytest.fixture
def notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    d = tmp_path / NOTES_DIR
    d.mkdir()
    (d / "a.txt").write_text("hello")
    (d / "sub").mkdir()
    (d / "sub" / "b.txt").write_text("bee")
    (tmp_path / "secret.txt").write_text("secret")
    return d


def test_reads_top_level_file(notes: Path) -> None:
    assert read_note("a.txt") == "hello"


def test_reads_subdirectory_file(notes: Path) -> None:
    assert read_note("sub/b.txt") == "bee"


def test_missing_file(notes: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name(notes: Path) -> None:
    assert read_note("") == ""


def test_directory_is_not_a_file(notes: Path) -> None:
    assert read_note("sub") == ""
    assert read_note(".") == ""


def test_parent_traversal(notes: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("..") == ""


def test_traversal_that_stays_inside(notes: Path) -> None:
    # Resolves to notes/a.txt, which is inside notes.
    assert read_note("sub/../a.txt") == "hello"


def test_absolute_path(notes: Path) -> None:
    assert read_note(str(notes.parent / "secret.txt")) == ""
    assert read_note(str(notes / "a.txt")) == ""


def test_absolute_looking_name(notes: Path) -> None:
    assert read_note("/etc/passwd") == ""


def test_backslash_traversal(notes: Path) -> None:
    assert read_note("..\\secret.txt") == ""


def test_null_byte(notes: Path) -> None:
    assert read_note("a.txt\x00../secret.txt") == ""
    assert read_note("\x00") == ""


def test_symlink_file_escaping(notes: Path) -> None:
    link = notes / "link.txt"
    try:
        os.symlink(notes.parent / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_note("link.txt") == ""


def test_symlink_dir_escaping(notes: Path, tmp_path: Path) -> None:
    outside = tmp_path / "outside"
    outside.mkdir()
    (outside / "x.txt").write_text("x")
    try:
        os.symlink(outside, notes / "dirlink", target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_note("dirlink/x.txt") == ""


def test_symlink_inside_notes_ok(notes: Path) -> None:
    try:
        os.symlink(notes / "a.txt", notes / "alias.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_note("alias.txt") == "hello"


def test_sibling_prefix_directory(notes: Path, tmp_path: Path) -> None:
    # "notes2" shares the string prefix "notes" but is outside it.
    sib = tmp_path / "notes2"
    sib.mkdir()
    (sib / "c.txt").write_text("sibling")
    assert read_note("../notes2/c.txt") == ""


def test_unreadable_file(notes: Path) -> None:
    p = notes / "locked.txt"
    p.write_text("x")
    p.chmod(0)
    try:
        if os.access(p, os.R_OK):
            pytest.skip("permissions not enforced (e.g. running as root)")
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o644)


def test_non_utf8_file_gives_empty(notes: Path) -> None:
    (notes / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    assert read_note("bin.dat") == ""

